#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = ClientCore

    public static func lift(_ handle: UInt64) throws -> ClientCore {
        return ClientCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: ClientCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ClientCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeClientCore_lift(_ handle: UInt64) throws -> ClientCore {
    return try FfiConverterTypeClientCore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeClientCore_lower(_ value: ClientCore) -> UInt64 {
    return FfiConverterTypeClientCore.lower(value)
}






/**
 * A sign-in in progress; see `yadorilink_client_core::session::LoginSession`.
 */
public protocol LoginSessionProtocol: AnyObject, Sendable {
    
    /**
     * Starts the flow and returns at once.
     *
     * # Errors
     * `InvalidInput` when already begun or cancelled; `PermissionDenied`
     * when this installation is already signed in.
     */
    func begin() throws 
    
    /**
     * Idempotent. Stops the flow; nothing is stored after this.
     */
    func cancel() 
    
    /**
     * The next event in order; `None` after the terminal event.
     *
     * Awaited in place rather than spawned: it only waits on the session's
     * queue, which needs no runtime, and so an abandoned call loses no event.
     */
    func nextEvent() async  -> LoginEvent?
    
}
/**
 * A sign-in in progress; see `yadorilink_client_core::session::LoginSession`.
 */
open class LoginSession: LoginSessionProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
